    out=[row[:] for row in grid]
    # red cell
    src=[(i,j) for i,row in enumerate(grid) for j,v in enumerate(row) if v==2][0]
    walls=[i for i,row in enumerate(grid) if 8 in row]
    wallset=set(walls)
