    for i in range(src[0]+1,h):
        if i in wallset:
            for j in gaps(i):
                if j in cols: out[i][j]=2
            # water passes only through gaps it covers; keep only those for below
            cols={j for j in cols if grid[i][j]==0}
            if not cols: break
        else:
            below = i+1
            if below<h and below in wallset:
                gp=gaps(below)
                lo,hi=min(cols),max(cols)
                if all(lo<=g<=hi for g in gp):
                    rng=range(0,w)   # all gaps inside span -> fill entire row
                else:
                    lo2=min([lo]+gp); hi2=max([hi]+gp)
                    rng=range(lo2,hi2+1)
                cols=set(rng)
                for j in rng: out[i][j]=2
            else:
                for j in cols: out[i][j]=2
