    out = [row[:] for row in grid]
    src = [(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v == 2][0]
    hwalls = max(row.count(8) for row in grid) > max(col.count(8) for col in zip(*grid))
    if hwalls:
        cell = lambda p, t: grid[p][t]; setc = lambda p, t, v: out[p].__setitem__(t, v)
        n_lines, n_t, start_p, start_t = h, w, src[0], src[1]
    else:
        cell = lambda p, t: grid[t][p]; setc = lambda p, t, v: out[t].__setitem__(p, v)
        n_lines, n_t, start_p, start_t = w, h, src[1], src[0]
    wallset = {p for p in range(n_lines) if sum(cell(p, t) == 8 for t in range(n_t)) > n_t // 2}
    gaps = lambda p: {t for t in range(n_t) if cell(p, t) == 0}
    setc(start_p, start_t, 2)
    ts = {start_t}
    # flow toward the nearest wall line (handles red starting on either side)
    w0 = min(wallset, key=lambda q: abs(q - start_p))
    d = 1 if w0 >= start_p else -1
    plines = range(start_p + d, n_lines, d) if d > 0 else range(start_p - 1, -1, -1)
    print('DBG plines', list(plines), 'wallset', wallset, 'd', d)
    for p in plines:
        if p in wallset:
            print('DBG wall line', p, 'ts', ts)
            ts = {t for t in ts if cell(p, t) == 0}
            for t in ts: setc(p, t, 2)
            if not ts:
                print('DBG break'); break
        elif p + 1 < n_lines and p + 1 in wallset:
            # landing model: only streams that actually land on an 8 spread;
            # a stream aligned with a gap falls straight through without spreading
            gp = gaps(p + 1); cover = set(ts)
            for t in ts:
                if cell(p + 1, t) != 8: continue
                a = t
                while a - 1 >= 0 and (a - 1) not in gp: a -= 1
                if a - 1 >= 0: a -= 1
                b = t
                while b + 1 < n_t and (b + 1) not in gp: b += 1
                if b + 1 < n_t: b += 1
                cover |= set(range(a, b + 1))
            for t in cover: setc(p, t, 2)
            ts = {t for t in cover if t in gp}
        else:
            for t in ts: setc(p, t, 2)
    return out

